import{_ as t,H as o,f as a,i as r}from"./chunks/framework.CGh9YNlq.js";const h=JSON.parse('{"title":"Agentic Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"notes/Workflows.md","filePath":"notes/Workflows.md"}'),n={name:"notes/Workflows.md"};function i(l,e,s,c,p,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="agentic-workflow" tabindex="-1">Agentic Workflow <a class="header-anchor" href="#agentic-workflow" aria-label="Permalink to &quot;Agentic Workflow&quot;">​</a></h1><p>有Agent能够自主决策的流程, 核心为AI agent参与流程，能规划，调用工具（Tool Calling），执行任务。自主决策自主执行，可以是一个固定的流程，e.g.一个agent自动读取邮件，总结并回复。适合场景：单一任务自动化。</p><p>A vertical slice of an application that corresponds to a customer use case. In GenAI, vertical slices like this often correspond to a user-driven(manual) workflow that is in the process of becoming AI assisted or fully automated.</p><h1 id="composable-agentic-workflows" tabindex="-1">Composable Agentic Workflows <a class="header-anchor" href="#composable-agentic-workflows" aria-label="Permalink to &quot;Composable Agentic Workflows&quot;">​</a></h1><p>可以被拆成模块，再像积木一样组合/复用的agentic workflow。核心为多个agent/tool/step 被设计成可插拔的模块，可以组合成不同的流程。特点为模块化、复用、编排、扩展。通常是多个reusable components。e.g.&quot;读取邮件 agent&quot; + &quot;分类 agent&quot; + &quot;写回复 agent&quot; + &quot;审批 step&quot;可以组合成不同的业务流程。适用场景：企业级复杂流程、多团队、多系统集成。</p><h1 id="system-architecture" tabindex="-1">System Architecture <a class="header-anchor" href="#system-architecture" aria-label="Permalink to &quot;System Architecture&quot;">​</a></h1><p>The system architecture involves five interacting components:</p><ul><li>Agents that implement each step of the workflow</li><li>A multiagent architecture that advances end users through the workflow</li><li>Gvernance, monitoring, and security components</li><li>A learning pipeline to continuously improve AI capability</li><li>An ongoing data creation, collection, and curation program</li></ul><p>*** An influential article from Anthropic on building effective agents(<a href="https://oreil.ly/7oEug" target="_blank" rel="noreferrer">https://oreil.ly/7oEug</a>) notes that &quot;the most successful implementations use simple, composable patterns rather than complex frameworks&quot; ***</p>',9)])])}const m=t(n,[["render",i]]);export{h as __pageData,m as default};
